        "meterTotal": {
          "type": "number",
          "description": "环形仪表倒计时总进度值",
          "sampleValue": 7
        },
        "meterLabel": {
          "type": "string",
          "description": "环形仪表中心短标签",
          "sampleValue": "待解禁"
        },
        "sleepHint": {
          "type": "string",
          "description": "夜晚休息和倒计时提示",
          "sampleValue": "夜间休息中"
        },
        "gameOneName": {
          "type": "string",
          "description": "常玩游戏名称一",
          "sampleValue": "我的世界"
        },
        "gameTwoName": {
          "type": "string",
          "description": "常玩游戏名称二",
          "sampleValue": "蛋仔派对"
        },
        "gameThreeName": {
          "type": "string",
          "description": "常玩游戏名称三",
          "sampleValue": "和平精英"
        },
        "actionLabel": {
          "type": "string",
          "description": "跳转到系统应用时长管理的动作短文案",
          "sampleValue": "时长管理"
        }
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/moon_z_fill_1.svg",
      "description": "月亮加 Z 的睡眠实心图标，适合表达夜间休息、睡眠模式和防沉迷晚间场景。"
    }
  ]
}

